export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  let thresholdsData = null;
  let passed = true;

  if (thresholds && typeof thresholds === 'object') {
    thresholdsData = [];
    for (const [metricId, minScore] of Object.entries(thresholds)) {
      const metric = evaluations.find((m) => m.id === metricId);
      const thresholdPassed = metric && metric.score !== null && metric.score >= minScore;
      if (!thresholdPassed) {
        passed = false;
      }
      thresholdsData.push({
        metric: metricId,
        min: minScore,
        score: metric?.score ?? null,
        passed: Boolean(thresholdPassed)
      });
    }
  }

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdsData) {
    report.passed = passed;
    report.thresholds = thresholdsData;
  }

  return report;
}

