function assertFileExists(targetPath: string) {
  if (!fs.existsSync(targetPath)) {
    throw new Error(`File not found: ${targetPath}`);
  }
}

function parseThresholds(thresholdStrings: string[] | undefined, validMetricIds: string[]): { thresholds: Record<string, number> | null; error?: string } {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { thresholds: null };
  }

  const thresholds: Record<string, number> = {};

  for (const thresholdStr of thresholdStrings) {
    const parts = thresholdStr.split('=');
    if (parts.length !== 2) {
      return {
        thresholds: null,
        error: `Invalid threshold format "${thresholdStr}": must be "metric=number"`
      };
    }

    const [metricId, minStr] = parts;
    const minScore = Number.parseFloat(minStr);

    if (!metricId.trim()) {
      return {
        thresholds: null,
        error: `Invalid threshold: metric id cannot be empty`
      };
    }

    if (Number.isNaN(minScore) || minScore < 0 || minScore > 1) {
      return {
        thresholds: null,
        error: `Invalid threshold: minimum must be a number between 0 and 1, got "${minStr}"`
      };
    }

    if (!validMetricIds.includes(metricId)) {
      return {
        thresholds: null,
        error: `Unknown metric id "${metricId}". Valid metrics: ${validMetricIds.join(', ')}`
      };
    }

    thresholds[metricId] = minScore;
  }

  return { thresholds };
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  const validMetricIds = evaluations.map((m: { id: string }) => m.id);
  const { thresholds, error } = parseThresholds(options.threshold, validMetricIds);

  if (error) {
    log.error('Invalid threshold option.', { error });
    process.exit(2);
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds && report.passed === false) {
    process.exit(1);
  }
}

