477	function parseThresholds(thresholdStrings: string[] | undefined, validMetricIds: string[]): { thresholds: Record<string, number> | null; error?: string } {
478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return { thresholds: null };
480	  }
481	
482	  const thresholds: Record<string, number> = {};
483	
484	  for (const thresholdStr of thresholdStrings) {
485	    const parts = thresholdStr.split('=');
486	    if (parts.length !== 2) {
487	      return {
488	        thresholds: null,
489	        error: `Invalid threshold format "${thresholdStr}": must be "metric=number"`
490	      };
491	    }
492	
493	    const [metricId, minStr] = parts;
494	    const minScore = Number.parseFloat(minStr);
495	
496	    if (!metricId.trim()) {
497	      return {
498	        thresholds: null,
499	        error: `Invalid threshold: metric id cannot be empty`
500	      };
501	    }
502	
503	    if (Number.isNaN(minScore) || minScore < 0 || minScore > 1) {
504	      return {
505	        thresholds: null,
506	        error: `Invalid threshold: minimum must be a number between 0 and 1, got "${minStr}"`
507	      };
508	    }
509	
510	    if (!validMetricIds.includes(metricId)) {
511	      return {
512	        thresholds: null,
513	        error: `Unknown metric id "${metricId}". Valid metrics: ${validMetricIds.join(', ')}`
514	      };
515	    }
516	
517	    thresholds[metricId] = minScore;
518	  }
519	
520	  return { thresholds };
521	}
